options.incomingScript:
function mapToDittoProtocolMsg(headers, textPayload, bytePayload, contentType) {
  var json = JSON.parse(textPayload);
  var topic = headers['mqtt.topic'];
  var parts = topic.split('/');
  var thingId = parts[2];
  var featureId = parts[4];
  var propName = parts[6];
  var namespace = thingId.split(':')[0];
  var name = thingId.split(':')[1];
  var path = '/features/' + featureId + '/properties/' + propName;
  return Ditto.buildDittoProtocolMsg(namespace, name, 'things', 'twin', 'commands', 'modify', path, headers, json.value);
}

options.outgoingScript:
function mapFromDittoProtocolMsg(namespace, name, group, channel, criterion, action, path, dittoHeaders, value, status, extra) {
  var payload = { "value": value };
  return Ditto.buildExternalMsg(dittoHeaders, JSON.stringify(payload));
}
